CREATE TABLE IF NOT EXISTS community_value_share_terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_shared_value_plans(id) ON DELETE CASCADE, term_type text NOT NULL, description text NOT NULL, beneficiary_group text, allocation_method text, target_value text, currency_code text, frequency text, status text NOT NULL DEFAULT 'Proposed', evidence_reference text, effective_from timestamptz, effective_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_value_milestones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_shared_value_plans(id) ON DELETE CASCADE, milestone_type text NOT NULL, title text NOT NULL, description text, target_date timestamptz, status text NOT NULL DEFAULT 'Planned', verification_status text NOT NULL DEFAULT 'Pending', evidence_reference text, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_value_monitoring (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_shared_value_plans(id) ON DELETE CASCADE, indicator text NOT NULL, target_value text, actual_value text, unit text, period_start timestamptz, period_end timestamptz, status text NOT NULL DEFAULT 'Pending', evidence_reference text, notes text, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_value_share_terms_plan ON community_value_share_terms(plan_id,status);
CREATE INDEX IF NOT EXISTS idx_value_milestones_plan ON community_value_milestones(plan_id,status,target_date);
CREATE INDEX IF NOT EXISTS idx_value_monitoring_plan ON community_value_monitoring(plan_id,recorded_at DESC);